-- Bahrain official secondary Arabic track-specific curricula, Semester 1, 2026-2027.
DO $$
DECLARE v_country uuid; v_curriculum uuid; v_grade uuid; v_unit uuid; v_track uuid;
BEGIN
 SELECT id INTO v_country FROM public.countries WHERE code='BH' AND is_active=true LIMIT 1;
 IF v_country IS NULL THEN RAISE EXCEPTION 'BH_COUNTRY_NOT_FOUND'; END IF;

 INSERT INTO public.curricula(country_id,name_ar,name_en,academic_year,description,is_active)
 VALUES(v_country,'اللغة العربية — التعليم الفني والمهني — الفصل الأول','Bahrain Arabic technical Semester 1','2026-2027','الخطة الرسمية الحالية للتعليم الفني والمهني، الفصل الدراسي الأول 2026-2027. المصدر: https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan3.pdf',true)
 ON CONFLICT(country_id,name_ar,academic_year) DO UPDATE SET description=EXCLUDED.description,is_active=true
 RETURNING id INTO v_curriculum;
 INSERT INTO public.grades(curriculum_id,name_ar,name_en,grade_number,sort_order,is_active)
 VALUES(v_curriculum,'الأول الثانوي','Grade 10',10,10,true)
 ON CONFLICT(curriculum_id,name_ar) DO UPDATE SET grade_number=EXCLUDED.grade_number,sort_order=EXCLUDED.sort_order,is_active=true
 RETURNING id INTO v_grade;
