 SELECT id INTO v_track FROM public.secondary_tracks
 WHERE country_code='BH' AND academic_year='2026-2027' AND track_name_ar='المسار الإداري والتكنولوجي - الهندسي' AND is_active=true LIMIT 1;
 IF v_track IS NULL THEN RAISE EXCEPTION 'BH_TRACK_NOT_FOUND'; END IF;

 UPDATE public.secondary_track_curricula SET is_default=false
 WHERE secondary_track_id=v_track AND relation_type IN ('official','track-specific');

 INSERT INTO public.secondary_track_curricula(secondary_track_id,curriculum_id,relation_type,is_default,notes)
 VALUES(v_track,v_curriculum,'track-specific',true,'الخطة الرسمية الحالية للمسار الإداري والتكنولوجي - الهندسي، الفصل الدراسي الأول 2026-2027.')
 ON CONFLICT(secondary_track_id,curriculum_id) DO UPDATE SET relation_type='track-specific',is_default=true,notes=EXCLUDED.notes;

 INSERT INTO public.secondary_track_units(secondary_track_id,unit_id,relation_type,notes)
 SELECT v_track,u.id,'track-specific','وحدة رسمية مستوردة من https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan5.pdf'
 FROM public.units u JOIN public.grades g ON g.id=u.grade_id WHERE g.curriculum_id=v_curriculum
 ON CONFLICT(secondary_track_id,unit_id) DO UPDATE SET relation_type='track-specific',notes=EXCLUDED.notes;

 UPDATE public.secondary_tracks
 SET lesson_coverage='detailed-current-semester-1',official_unit_scope='mapped-only',
     source_urls=(SELECT jsonb_agg(DISTINCT value) FROM jsonb_array_elements(coalesce(source_urls,'[]'::jsonb) || to_jsonb(ARRAY['https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan5.pdf']::text[]))),
     updated_at=now()
 WHERE id=v_track;

 INSERT INTO public.secondary_track_terms(secondary_track_id,academic_year,semester,publication_status,detail_status,source_url,audited_at,notes)
 VALUES(v_track,'2026-2027',1,'published','detailed-imported','https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan5.pdf',date '2026-10-06','الخطة الرسمية الحالية للمسار الإداري والتكنولوجي - الهندسي، الفصل الدراسي الأول 2026-2027.')
 ON CONFLICT(secondary_track_id,academic_year,semester)
 DO UPDATE SET publication_status='published',detail_status='detailed-imported',source_url=EXCLUDED.source_url,audited_at=EXCLUDED.audited_at,notes=EXCLUDED.notes;
 UPDATE public.secondary_tracks
 SET lesson_coverage='current-detailed-source-nonstandard-levels',
     source_urls=(SELECT jsonb_agg(DISTINCT value) FROM jsonb_array_elements(coalesce(source_urls,'[]'::jsonb) || to_jsonb(ARRAY['https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf']::text[]))),
     updated_at=now()
 WHERE country_code='BH' AND academic_year='2026-2027' AND track_name_ar='التعليم المستمر';

 UPDATE public.secondary_track_terms tt
 SET publication_status='published',detail_status='partial-imported',
     source_url='https://edunet.bh/manual/plans1-2026-2027/Arabic/Plan6.pdf',audited_at=date '2026-10-06',
     notes='الخطة الحالية 2026-2027 متاحة تفصيليًا، لكنها منظمة بمستويات محو الأمية/متابعة/تقوية لا بصفوف 10-12؛ لم تُخترع مطابقة رقمية.'
 FROM public.secondary_tracks st
 WHERE tt.secondary_track_id=st.id AND st.country_code='BH' AND st.academic_year='2026-2027'
   AND st.track_name_ar='التعليم المستمر' AND tt.academic_year='2026-2027' AND tt.semester=1;
END $$;
